#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 32

#define SENSOR_PIN A0

// WPGH GoFast
const float SENSOR_EMPTY = 0.8;  // Вольт
const float SENSOR_FULL  = 4.5;  // Вольт

// Объем бака
const float TANK_VOLUME = 54.0;  // литров

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

// Сглаженное значение
float filteredVoltage = SENSOR_EMPTY;

void setup() {

  // OLED
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    while (true);
  }

  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);

  // Приветствие
  display.setTextSize(2);
  display.setCursor(34, 8);
  display.println("HELLO");
  display.display();

  delay(2000);

  // Первое измерение
  int raw = analogRead(SENSOR_PIN);
  filteredVoltage = raw * (5.0 / 1023.0);
}

void loop() {

  // Читаем датчик
  int raw = analogRead(SENSOR_PIN);

  // Переводим ADC в напряжение
  float voltage = raw * (5.0 / 1023.0);

  // Сглаживание
  // Чем меньше число, тем плавнее показания
  filteredVoltage = filteredVoltage * 0.95 + voltage * 0.05;

  // Ограничиваем диапазон
  if (filteredVoltage < SENSOR_EMPTY) {
    filteredVoltage = SENSOR_EMPTY;
  }

  if (filteredVoltage > SENSOR_FULL) {
    filteredVoltage = SENSOR_FULL;
  }

  // Перевод напряжения в проценты
  float percent =
    (filteredVoltage - SENSOR_EMPTY) /
    (SENSOR_FULL - SENSOR_EMPTY) * 100.0;

  // Ограничение процентов
  if (percent < 0) percent = 0;
  if (percent > 100) percent = 100;

  // Расчет литров
  float liters = TANK_VOLUME * percent / 100.0;

  // Экран
  display.clearDisplay();

  display.setTextSize(2);
  display.setCursor(0, 8);

  display.print("GAS ");
  display.print((int)percent);
  display.print("% ");

  display.print(liters, 1);
  display.print(" L");

  display.display();

  // Частота обновления
  delay(500);
}
